'use client';

import React, { useState, useEffect } from 'react';
import { getSLAState, getRemainingSeconds } from '../../utils/slaUtils';
import { useKDSSound } from '../sound/useKDSSound';

interface TicketTimerProps {
    createdAt: string;
    prepTimeMinutes: number;
}

export const TicketTimer: React.FC<TicketTimerProps> = ({ createdAt, prepTimeMinutes }) => {
    const [remainingSeconds, setRemainingSeconds] = useState(getRemainingSeconds(createdAt, prepTimeMinutes));
    const [slaState, setSlaState] = useState(getSLAState(createdAt, prepTimeMinutes));
    const [elapsedMinutes, setElapsedMinutes] = useState(0);
    const { playSound } = useKDSSound();
    const hasPlayedBreach = React.useRef(false);

    useEffect(() => {
        const updateTimer = () => {
            const remaining = getRemainingSeconds(createdAt, prepTimeMinutes);
            const state = getSLAState(createdAt, prepTimeMinutes);

            const createdTime = new Date(createdAt).getTime();
            const now = Date.now();
            const elapsed = Math.floor((now - createdTime) / 60000);

            setRemainingSeconds(remaining);
            setSlaState(state);
            setElapsedMinutes(elapsed);

            if (state === 'OVERDUE' && !hasPlayedBreach.current) {
                playSound('SLA_BREACH');
                hasPlayedBreach.current = true;
            } else if (state !== 'OVERDUE') {
                hasPlayedBreach.current = false;
            }
        };

        updateTimer();
        const interval = setInterval(updateTimer, 1000);

        return () => clearInterval(interval);
    }, [createdAt, prepTimeMinutes]);

    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    };

    const getStateClasses = () => {
        switch (slaState) {
            case 'OVERDUE':
                return 'border-[var(--kds-status-late)] text-[var(--kds-status-late)] font-black shadow-none';
            case 'WARNING':
                return 'border-[var(--kds-status-warning)] text-[var(--kds-status-warning)] font-black shadow-none';
            default:
                return 'border-[var(--kds-border)] text-white font-black shadow-none';
        }
    };

    return (
        <div className={`flex flex-col items-end gap-1 p-2 rounded-lg border-2 transition-all duration-300 ${getStateClasses()}`}>
            <div className="flex items-center gap-2">
                <span className="text-[10px] font-black uppercase tracking-widest opacity-60">REMAINING:</span>
                <span className="font-[var(--kds-font-main)] text-[var(--kds-font-timer)] font-black tabular-nums leading-none">
                    {formatTime(remainingSeconds)}
                </span>
            </div>
            <div className="flex items-center gap-2">
                <span className="text-[10px] font-black uppercase tracking-widest opacity-60">ELAPSED:</span>
                <span className="text-xl font-black">{elapsedMinutes} MIN</span>
            </div>
            <div className="text-[9px] font-black uppercase tracking-tighter">
                Status: {slaState.replace('_', ' ')}
            </div>
        </div>
    );
};
